export const SettingsProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [theme, setThemeState] = useState<Theme>('light');
  const [language, setLanguageState] = useState<Language>('am');
  const [calendarType, setCalendarTypeState] = useState<CalendarType>('ethiopian');
  const [timeSystem, setTimeSystemState] = useState<TimeSystem>('ethiopian');
  const [userProfile, setUserProfileState] = useState<UserProfile>({
    name: 'Alexander Mitchell',
    businessName: 'Elite Hardware',
    avatarIndex: 0,
    avatarUri: undefined,
  });
  const [notifications, setNotificationsState] = useState<NotificationSettings>({
    stock: true,
    expiration: true,
    daily: true,
    credit: true,
    debt: true,
    recurring: true,
    weeklySummary: true,
    monthlySummary: true,
  });
  const [pin, setPinState] = useState<string | null>(null);
  const [recoveryCodeExists, setRecoveryCodeExistsState] = useState<boolean>(false);
  const [soundEnabled, setSoundEnabledState] = useState<boolean>(true);
  const [dashboardVisibility, setDashboardVisibility] = useState<{
    alerts: boolean;
    businessHealth: boolean;
    businessAssistant: boolean;
  }>({
    alerts: true,
    businessHealth: true,
    businessAssistant: true,
  });
  const [featureFlags, setFeatureFlagsState] = useState<FeatureFlags>({
    warehousesEnabled: getFeatureFlag('warehouses', true),
    shipmentsEnabled: getFeatureFlag('shipments', true),
    customersEnabled: getFeatureFlag('customers', true),
  });

  const setFeatureFlag = useCallback((key: FeatureFlagKey, value: boolean) => {
    setFeatureFlagsState((prev) => ({ ...prev, [key === 'warehouses' ? 'warehousesEnabled' : key === 'shipments' ? 'shipmentsEnabled' : 'customersEnabled']: value }));
    persistFeatureFlag(key, value);
  }, []);

  const setSoundEnabled = useCallback((val: boolean) => {
    setSoundEnabledState(val);
    setSoundServiceEnabled(val);
    SecureStore.setItemAsync('settings_sound_enabled', JSON.stringify(val)).catch(() => {});
  }, []);

  // Load settings on mount
  useEffect(() => {
    const loadSettings = async () => {
      const setupComplete = await SecureStore.getItemAsync('user_setupComplete');

      const savedTheme = await SecureStore.getItemAsync('settings_theme') as Theme;
      if (savedTheme && setupComplete === 'true') {
        setThemeState(savedTheme);
      }

      const savedLang = await SecureStore.getItemAsync('settings_language') as Language;
      if (savedLang && setupComplete === 'true') setLanguageState(savedLang);

      const savedCalendar = await SecureStore.getItemAsync('settings_calendar') as CalendarType;
      if (savedCalendar) setCalendarTypeState(savedCalendar);

      const savedTimeSystem = await SecureStore.getItemAsync('settings_time_system') as TimeSystem;
      if (savedTimeSystem === 'device' || savedTimeSystem === 'ethiopian') {
        setTimeSystemState(savedTimeSystem);
      }

      const savedProfile = await SecureStore.getItemAsync('settings_profile');
      if (savedProfile) {
        const parsed = JSON.parse(savedProfile);
        // Merge with defaults so avatarUri won't be lost if missing
        setUserProfileState({ avatarIndex: 0, avatarUri: undefined, ...parsed });
      }

      const savedNotes = await SecureStore.getItemAsync('settings_notifications');
      if (savedNotes) setNotificationsState(JSON.parse(savedNotes));

      const savedSound = await SecureStore.getItemAsync('settings_sound_enabled');
      if (savedSound !== null) {
        const parsed = JSON.parse(savedSound);
        setSoundEnabledState(parsed);
        setSoundServiceEnabled(parsed);
      }

      const savedDashboardVisibility = await SecureStore.getItemAsync('settings_dashboard_visibility');
      if (savedDashboardVisibility) {
        const parsed = JSON.parse(savedDashboardVisibility);
        setDashboardVisibility(parsed);
      }

      // PIN is stored only as a salted hash. The in-memory flag simply
      // signals "a PIN is set" — it never holds the PIN value itself.
      const pinIsSet = await hasPinHash();
      setPinState(pinIsSet ? 'set' : null);

      const recoveryExists = await hasRecoveryCode();
      setRecoveryCodeExistsState(recoveryExists);
    };
    loadSettings();
  }, []);

  const setTheme = async (val: Theme) => {
    setThemeState(val);
    await SecureStore.setItemAsync('settings_theme', val);
  };

  const setLanguage = async (val: Language) => {
    setLanguageState(val);
    await SecureStore.setItemAsync('settings_language', val);
  };

  const setCalendarType = async (val: CalendarType) => {
    setCalendarTypeState(val);
    await SecureStore.setItemAsync('settings_calendar', val);
  };

  const setTimeSystem = async (val: TimeSystem) => {
    setTimeSystemState(val);
    await SecureStore.setItemAsync('settings_time_system', val);
  };

  const setUserProfile = async (val: UserProfile) => {
    setUserProfileState(val);
    await SecureStore.setItemAsync('settings_profile', JSON.stringify(val));
    await SecureStore.setItemAsync('user_avatarIndex', val.avatarIndex.toString());
  };

  const setNotifications = async (val: NotificationSettings) => {
    setNotificationsState(val);
    await SecureStore.setItemAsync('settings_notifications', JSON.stringify(val));
  };

  const setPin = async (val: string | null) => {
    if (val) {
      // Store only the salted SHA-256 hash — never the PIN in plain text.
      await storePinHash(val);
      setPinState('set');
      // Best-effort: purge any legacy plain-text PIN left by older builds.
      try { await SecureStore.deleteItemAsync('settings_pin'); } catch {}
    } else {
      await removePinHash();
      setPinState(null);
    }
  };

  // Re-check whether a PIN is currently set (e.g. after external mutation).
  const refreshPinStatus = async () => {
    const pinIsSet = await hasPinHash();
    setPinState(pinIsSet ? 'set' : null);
  };

  const setRecoveryCodeExists = (exists: boolean) => {
    setRecoveryCodeExistsState(exists);
  };

  const toggleDashboardSection = async (section: 'alerts' | 'businessHealth' | 'businessAssistant', value?: boolean) => {
    setDashboardVisibility(prev => {
      const newVisibility = { ...prev, [section]: value !== undefined ? value : !prev[section] };
      SecureStore.setItemAsync('settings_dashboard_visibility', JSON.stringify(newVisibility)).catch(() => {});
      return newVisibility;
    });
  };

  const t = (key: string, params?: Record<string, string>) => {
    let text = translations[language][key] || translations['en'][key] || key;
    if (params) {
      if (params.count !== undefined) {
        const count = Number(params.count);
        if (!isNaN(count)) {
          const pluralKey = count === 1 ? `${key}_one` : `${key}_other`;
          const pluralText = translations[language][pluralKey] || translations['en'][pluralKey];
          if (pluralText) text = pluralText;
        }
      }
      Object.keys(params).forEach(p => {
        text = text.split(`{${p}}`).join(String(params[p]));
      });
    }
    return text;
  };

  const getThemeColors = (t: Theme) => {
    switch (t) {
      case 'dark': return DarkTheme;
      case 'light': return LightTheme;
      default: return LightTheme;
    }
  };

  const colors = getThemeColors(theme);
  return (
    <SettingsContext.Provider value={{
      theme, language, calendarType, timeSystem, userProfile, notifications, soundEnabled, pin, recoveryCodeExists, dashboardVisibility, featureFlags, setFeatureFlag,
      setTheme, setLanguage, setCalendarType, setTimeSystem, setUserProfile, setNotifications, setSoundEnabled, setPin, setRecoveryCodeExists, refreshPinStatus, toggleDashboardSection, t, colors
    }}>
      {children}
    </SettingsContext.Provider>
  );
};

export const useSettings = () => {
  const context = useContext(SettingsContext);
  if (context === undefined) {
    console.warn('useSettings called outside SettingsProvider – using fallback defaults');
    // Return safe defaults so the app doesn't crash during mount race conditions
    const fallback: SettingsContextType = {
      theme: 'dark',
      language: 'en',
      calendarType: 'ethiopian',
      timeSystem: 'ethiopian',
      userProfile: { name: '', businessName: '', avatarIndex: 0 },
      notifications: { stock: true, expiration: true, daily: true, credit: true, debt: true, recurring: true, weeklySummary: true, monthlySummary: true },
      soundEnabled: true,
      pin: null,
      recoveryCodeExists: false,
      dashboardVisibility: { alerts: true, businessHealth: true, businessAssistant: true },
      featureFlags: { warehousesEnabled: true, shipmentsEnabled: true, customersEnabled: true },
      setFeatureFlag: () => {},
      toggleDashboardSection: async () => {},
      setTheme: async () => {},
      setLanguage: async () => {},
      setCalendarType: async () => {},
      setTimeSystem: async () => {},
      setUserProfile: async () => {},
      setNotifications: async () => {},
      setSoundEnabled: () => {},
      setPin: async () => {},
      setRecoveryCodeExists: () => {},
      refreshPinStatus: async () => {},
      t: (key: string) => key,
      colors: DarkTheme,
    };
    return fallback;
  }
  return context;
};

export const useDashboardVisibility = () => {
  const context = useContext(SettingsContext);
  if (context === undefined) {
    return {
      dashboardVisibility: { alerts: true, businessHealth: true, businessAssistant: true },
      toggleDashboardSection: async () => {},
    };
  }
  return {
    dashboardVisibility: context.dashboardVisibility,
    toggleDashboardSection: context.toggleDashboardSection,
  };
};







